{ 
    int i = 0, j = 0; 
    while (str[i]) 
    { 
        if (str[i] != ' ') 
            str[j++] = str[i]; 
        else if (str[i-1] != ' ') 
            str[j++] = str[i];  
        i++; 
    } 
    str[j] = '\0';  
} 

