    let result;
    let delta = (b * b) - (4 * a * c);
    if (delta > 0) {
      result = {
        root1: (-b + Math.sqrt(delta)) / (2 * a),
        root2: (-b - Math.sqrt(delta)) / (2 * a)
      };
    }
    else if (delta == 0) {
      result = {
        root1: (-b + Math.sqrt(delta)) / (2 * a)
      };
    }
    else {
      result = {
        root1: 'cannot calculate the roots'
      };
    }
    return result;
  }

