function twoNumSum(arr, targetSum) {
  let hash = {};

  for(let i = 0; i < arr.length; i++){
    let current = arr[i];

    if(hash[current] !== undefined) return [hash.current, i];
    else hash[targetSum - current] = i;
  }

  return [];
}

